package com.rationportal.service; import com.rationportal.model.OnorcPortability; import com.rationportal.repository.OnorcPortabilityRepository; import org.springframework.stereotype.Service; import java.util.UUID; @Service public class OnorcPortabilityService { private final OnorcPortabilityRepository repo; public OnorcPortabilityService(OnorcPortabilityRepository repo){this.repo=repo;} public OnorcPortability create(OnorcPortability p,String email){p.setReferenceNumber("ONORC"+UUID.randomUUID().toString().replace("-","").substring(0,10).toUpperCase()); p.setRequestedBy(email.toLowerCase()); p.setStatus("REQUESTED"); return repo.save(p);} }
